<section id="branchManagement" hidden aria-label="Gestión de sucursales">
<div class="branch-admin-toolbar"><label class="branch-admin-search"><?= stock_icon('search') ?><input id="manageBranchSearch" type="search" maxlength="160" placeholder="Nombre, dirección o provincia" aria-label="Buscar sucursales"></label><button id="manageBranchAdd" class="library-primary stock-icon" type="button" title="Agregar sucursal" aria-label="Cargar sucursal"><?= stock_icon('plus') ?><span>Cargar sucursal</span></button></div>
<p id="manageBranchStatus" class="library-status" role="status"></p><div id="manageBranchList"></div><div id="manageBranchPages" class="library-dialog-actions" hidden><button id="manageBranchPrevious" type="button" class="library-secondary" aria-label="Página anterior"><?= stock_icon('chevron') ?></button><span id="manageBranchPage"></span><button id="manageBranchNext" type="button" class="library-secondary" aria-label="Página siguiente"><?= stock_icon('chevron') ?></button></div>
</section>
<dialog id="manageBranchDialog" class="library-dialog branch-dialog" aria-labelledby="manageBranchTitle"><div class="library-heading"><h2 id="manageBranchTitle"><?= stock_icon('branch') ?> <span>Editar sucursal</span></h2><button type="button" class="app-close" id="manageBranchClose" aria-label="Cerrar"><?= stock_icon('close') ?></button></div><div id="manageBranchBody" class="branch-dialog-body"><p id="manageBranchNotice" class="library-status" role="status"></p><form id="manageBranchForm"><details id="manageBranchLocation" class="branch-point-details"><summary><?= stock_icon('branch') ?> Ubicación en el mapa<span class="branch-create-chevron"><?= stock_icon('chevron') ?></span></summary><div class="branch-map-frame"><div id="manageBranchMap" class="branch-map"></div><div class="branch-map-controls"><button id="manageBranchLocate" class="library-secondary" type="button" aria-label="Centrar en mi ubicación" title="Centrar en mi ubicación"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M12 2v4m0 12v4M2 12h4m12 0h4M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0"/></svg></button><button id="manageBranchClearPoint" class="library-secondary" type="button" aria-label="Quitar ubicación" title="Quitar ubicación"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0ZM9 7l6 6m0-6-6 6"/></svg></button></div></div><p id="manageBranchMapStatus" class="stock-muted" role="status"></p></details><label>Nombre<input name="name" required maxlength="100" placeholder="Ej.: Carrefour Centro"></label><div id="manageBranchMatches" class="branch-admin-matches" hidden></div><label>Dirección<input name="address" required maxlength="160" placeholder="Ej.: Av. Colón 1234"></label><div class="branch-form-row"><label>Localidad<input name="locality" required maxlength="100" placeholder="Ej.: Córdoba"></label><label>Provincia<input name="province" required maxlength="80" placeholder="Ej.: Córdoba"></label></div><label>Descripción <small>(opcional)</small><textarea name="description" maxlength="300" rows="2" placeholder="Ej.: Entrada por la calle lateral"></textarea></label><input name="latitude" type="hidden"><input name="longitude" type="hidden"></form></div><div class="branch-dialog-footer"><button id="saveManageBranch" type="submit" form="manageBranchForm" class="library-primary"><?= stock_icon('check') ?> Guardar cambios</button></div></dialog>

<dialog id="manageBranchPalletDialog" class="library-dialog branch-dialog" aria-labelledby="manageBranchPalletTitle"><div class="library-heading"><h2 id="manageBranchPalletTitle"><?= stock_icon('pallet') ?>Palets vinculados</h2><button id="manageBranchPalletClose" type="button" class="app-close" aria-label="Cerrar palets vinculados"><?= stock_icon('close') ?></button></div><p id="manageBranchPalletName" class="stock-muted"></p><p id="manageBranchPalletStatus" role="status" class="library-status"></p><div id="manageBranchPalletList"></div><button id="manageBranchPalletMore" type="button" class="library-secondary" hidden>Ver más</button></dialog>
